package com.axison.coding;

public class Questions {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		// swapping 2 values
		
		int a = 10;
		int b = 5; 
		System.out.println(a);
		System.out.println(b);
		a = a + b;
		b = a - b;
		a = a - b;
		System.out.println("After swapping");
		System.out.println(a);
		System.out.println(b);
		
		

	}

}
